const data = $json;

const requiredFields = [
  "PO Number",
  "Supplier Name",
  "Supplier Email",
  "Buyer Name",
  "Buyer Email",
  "Order Date",
  "Delivery Date",
  "Product Details"
];

const missingFields = requiredFields.filter(
  field =>
    data[field] === undefined ||
    data[field] === null ||
    data[field] === ""
);

return {
  json: {
    ...data,
    data_valid: missingFields.length === 0,
    missing_fields: missingFields
  }
};

